def mask_for(t,im):
 fine=np.zeros((360,640),np.uint8);coarse=fine.copy()
 for tr in TRACKS:
  keys=tr['keys']
  if not keys[0][0]<=t<=keys[-1][0]:continue
  ts=np.array([z[0] for z in keys]);i=np.searchsorted(ts,t)
  if i==0:b=np.array(keys[0][1:])
  elif i==len(keys):b=np.array(keys[-1][1:])
  else:
   a,z=keys[i-1:i+1];q=(t-a[0])/(z[0]-a[0]);b=np.array(a[1:])*(1-q)+np.array(z[1:])*q
  p=tr['pad'];x0,y0,x1,y1=b;x0=max(0,int(x0-p));x1=min(640,int(x1+p));y0=max(0,int(y0-p));y1=min(360,int(y1+p))
  if x1<=x0 or y1<=y0:continue
  m=coarse if tr['block']==20 else fine
  if tr['name']=='glass architecture first pass':
   # Opaque white chair surfaces in front of the dark graphic. A brightness
   # threshold is used only inside the manually specified glass region.
   q=im[y0:y1,x0:x1];hsv=cv2.cvtColor(q,cv2.COLOR_BGR2HSV)
   fg=(q.min(2)>155)&(hsv[:,:,1]<45)
   fg=cv2.morphologyEx(fg.astype(np.uint8),cv2.MORPH_OPEN,np.ones((5,5),np.uint8))>0
   m[y0:y1,x0:x1][~fg]=255
  else:m[y0:y1,x0:x1]=255
 return fine,coarse
def edit_camera(t,im):
 fine,coarse=mask_for(t,im);out=im.copy()
 for mask,block in [(fine,12),(coarse,20)]:
  pix=cv2.resize(cv2.resize(im,(round(640/block),round(360/block)),interpolation=cv2.INTER_AREA),(640,360),interpolation=cv2.INTER_NEAREST)
  out[mask>0]=pix[mask>0]
 return out

def refine(name,updates):
 tr=next(z for z in TRACKS if z['name']==name);keys={z[0]:z for z in tr['keys']};keys.update({z[0]:z for z in updates});tr['keys']=[keys[t] for t in sorted(keys)]
