# Inspection seeks round to an actual decoded presentation timestamp. Apply
# that small correction to the manually keyed times before interpolation.
def retime_tracks():
 import json
 from pathlib import Path
 p=Path(__file__).resolve().parent/'inspect/anchor-pts.json'
 if not p.exists():return
 mapping=json.loads(p.read_text())
 for tr in TRACKS:
  rows={}
  for k in tr['keys']:
   tt=mapping.get(str(k[0]),k[0]);rows[tt]=[tt,*k[1:]]
  tr['keys']=[rows[t] for t in sorted(rows)]
retime_tracks()
